        items={items}
        renderSwitcher={({ onClick, onKeyDown }) => (
          <Button view="outlined" onClick={onClick} onKeyDown={onKeyDown}>
            Действия
          </Button>
        )}
      />
      {lastAction && <Text>Выбрано действие: {lastAction}</Text>}
    </div>
  );
}
